let sidebarContextMenu = null;

function closeSidebarContextMenu() {
  sidebarContextMenu?.remove();
  sidebarContextMenu = null;
  document.querySelectorAll('[data-workspace-menu-toggle], [data-session-menu-toggle]').forEach(button => {
    button.setAttribute('aria-expanded', 'false');
  });
}

function openSidebarContextMenu(anchor, items) {
  closeSidebarContextMenu();
  const menu = document.createElement('div');
  menu.className = 'sidebar-context-menu';
  menu.setAttribute('role', 'menu');
  items.forEach(item => {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = `sidebar-context-menu-item${item.danger ? ' danger' : ''}`;
    button.innerHTML = `${item.icon || ''}<span>${escapeHtml(item.label)}</span>`;
    button.addEventListener('click', async event => {
      event.stopPropagation();
      closeSidebarContextMenu();
      await item.onSelect?.();
    });
    menu.appendChild(button);
  });
  document.body.appendChild(menu);
  sidebarContextMenu = menu;
  anchor.setAttribute('aria-expanded', 'true');

  const rect = anchor.getBoundingClientRect();
  const menuRect = menu.getBoundingClientRect();
  const left = Math.min(window.innerWidth - menuRect.width - 8, Math.max(8, rect.right - menuRect.width));
  const below = rect.bottom + 5;
  const top = below + menuRect.height <= window.innerHeight - 8
    ? below
    : Math.max(8, rect.top - menuRect.height - 5);
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
}

document.addEventListener('pointerdown', event => {
  if (event.target.closest('.sidebar-context-menu, [data-workspace-menu-toggle], [data-session-menu-toggle]')) return;
  closeSidebarContextMenu();
});
window.addEventListener('resize', closeSidebarContextMenu);

let sessionTitleResizeObserver = null;
let sessionTitleMeasureFrame = 0;

function syncSessionTitleOverflow(list = $('#sessionList')) {
  if (!list?.isConnected) return;
  list.querySelectorAll('.session-title-shell').forEach(shell => {
    const text = shell.querySelector('.session-title-text');
    const item = shell.closest('.session-item');
    if (!text || !item) return;
    item.classList.remove('has-overflow-title');
    item.style.removeProperty('--session-marquee-distance');
    item.style.removeProperty('--session-marquee-duration');

    const textWidth = Math.ceil(text.scrollWidth);
    const availableWidth = Math.floor(shell.clientWidth);
    if (textWidth <= availableWidth + 1) return;
    const distance = textWidth + 24;
    item.classList.add('has-overflow-title');
    item.style.setProperty('--session-marquee-distance', `${distance}px`);
    item.style.setProperty('--session-marquee-duration', `${Math.max(5.5, Math.min(14, distance / 28)).toFixed(2)}s`);
  });
}

function scheduleSessionTitleOverflowSync(list = $('#sessionList')) {
  cancelAnimationFrame(sessionTitleMeasureFrame);
  sessionTitleMeasureFrame = requestAnimationFrame(() => syncSessionTitleOverflow(list));
}

function trackSessionTitleOverflow(list) {
  sessionTitleResizeObserver?.disconnect();
  sessionTitleResizeObserver = null;
  if (typeof ResizeObserver === 'function') {
    sessionTitleResizeObserver = new ResizeObserver(() => scheduleSessionTitleOverflowSync(list));
    sessionTitleResizeObserver.observe(list);
  }
  scheduleSessionTitleOverflowSync(list);
}

window.addEventListener('resize', () => scheduleSessionTitleOverflowSync());

function normalizeWorkspaceUiPath(workspace) {
  const value = String(workspace || '').trim().split('\\').join('/');
  let end = value.length;
  while (end > 0 && value[end - 1] === '/') end -= 1;
  return value.slice(0, end);
}

function workspaceGroupKey(sessionOrWorkspace) {
  const workspace = typeof sessionOrWorkspace === 'string'
    ? sessionOrWorkspace
    : String(sessionOrWorkspace?.workspace || '');
  const value = normalizeWorkspaceUiPath(workspace);
  return value ? value.toLowerCase() : 'blank';
}

function workspaceGroupLabel(workspace) {
  const value = normalizeWorkspaceUiPath(workspace);
  if (!value) return 'blank';
  return value.split('/').filter(Boolean).pop() || value;
}

async function toggleSessionPinnedFromSidebar(session) {
  const updated = await api.setSessionPinned(session.id, !session.pinned);
  if (!updated) {
    toast('任务置顶状态更新失败');
    return;
  }
  if (state.currentSession?.id === session.id) state.currentSession.pinned = !!updated.pinned;
  const summary = state.sessions.find(item => item.id === session.id);
  if (summary) summary.pinned = !!updated.pinned;
  await refreshSessions();
  updateTaskBar();
  toast(updated.pinned ? '任务已置顶' : '已取消置顶任务');
}

let sessionDeletionUiQueue = Promise.resolve();

function deleteSessionFromSidebar(id) {
  const operation = sessionDeletionUiQueue.then(() => performSessionDeletionFromSidebar(id));
  sessionDeletionUiQueue = operation.catch(() => {});
  return operation;
}

async function performSessionDeletionFromSidebar(id) {
  if (isSessionExecutionActive(id)) {
    toast('任务运行中，无法删除');
    return;
  }
  const summary = state.sessions.find(session => session.id === id);
  const session = state.currentSession?.id === id
    ? state.currentSession
    : (await api.getSession(id, { messageLimit: 1 }).catch(() => null)) || summary;
  let confirmed = false;
  if (!isBlankNewChat(session)) {
    confirmed = await requestSessionDeleteConfirmation(session);
    if (!confirmed) return;
  }
  const result = await api.deleteSession(id, confirmed);
  if (result?.ok === false) {
    toast(result.error || '删除失败');
    return;
  }
  await clearYanCoreQueuedIntentsForThread(id, 'session_removed');
  state.composerDrafts.delete(String(id));
  state.queuedTurns.delete(String(id));
  if (state.currentSession?.id === id) {
    state.currentSession = null;
    restoreComposerDraftForSession('');
    clearMessages();
  }
  await refreshSessions();
  if (!state.currentSession) {
    const replacementId = result.replacementSession?.id;
    const nextId = replacementId && state.sessions.some(session => session.id === replacementId)
      ? replacementId
      : state.sessions[0]?.id;
    if (nextId) await loadSession(nextId);
    else await newSession();
  }
  toast(result.replacedLast ? '已移除任务，已新建空白任务' : '已移除任务');
}

// Hint below the composer: shown while the CURRENT task is still a brand-new
// blank task, and removed the moment that task stops being new — independent of
// how many other tasks the profile already has.
function updateGuideHint(isNewTask) {
  const hint = $('#guideHint');
  if (!hint) return;
  const show = isNewTask === undefined
    ? $('#pageChat')?.classList.contains('empty') === true
    : !!isNewTask;
  hint.classList.toggle('hidden', !show);
}

function renderSessionList() {
  updateGuideHint();
  const list = $('#sessionList');
  const groups = new Map();
  const pinnedSessions = state.sessions
    .filter(session => !!session.pinned)
    .sort((a, b) => (Number(b.updatedAt) || 0) - (Number(a.updatedAt) || 0));

  state.sessions.forEach(session => {
    const workspace = String(session.workspace || '').trim();
    const key = workspaceGroupKey(session);
    const label = workspaceGroupLabel(workspace);
    if (!groups.has(key)) groups.set(key, {
      key,
      workspace,
      label,
      sessions: [],
      latest: 0,
      pinned: !!workspaceSidebarMeta[key]?.pinned
    });
    const group = groups.get(key);
    if (!session.pinned) group.sessions.push(session);
    group.latest = Math.max(group.latest, Number(session.updatedAt) || 0);
  });

  const visibleGroups = [...groups.values()]
    .filter(group => !workspaceSidebarMeta[group.key]?.hidden)
    .sort((a, b) => {
      if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;
      return b.latest - a.latest;
    });

  if (visibleGroups.length === 0 && pinnedSessions.length === 0) {
    list.innerHTML = '<div class="session-empty">暂无对话 · 点击上方开始</div>';
    trackSessionTitleOverflow(list);
    return;
  }

  const renderSessionRow = (session, { pinnedSection = false } = {}) => {
    const running = isSessionRunning(session.id);
    const dead = session.workspaceMissing === true;
    return `
      <div class="session-item ${pinnedSection ? 'pinned-session-item' : ''} ${state.currentSession && session.id === state.currentSession.id ? 'active' : ''} ${running ? 'running' : ''} ${session.pinned ? 'pinned' : ''} ${dead ? 'is-dead-workspace' : ''}" data-id="${escapeAttr(session.id)}"${dead ? ' title="该任务所在的工作区已被删除"' : ''}>
        ${running ? '<span class="session-spinner"></span>' : ''}
        <span class="session-title-shell">
          <span class="session-title-track">
            <span class="session-title-text">${escapeHtml(displaySessionTitle(session.title))}</span>
            <span class="session-title-copy" aria-hidden="true">${escapeHtml(displaySessionTitle(session.title))}</span>
          </span>
        </span>
        <button type="button" class="session-more-btn" data-session-menu-toggle="${escapeAttr(session.id)}" aria-label="任务操作" aria-expanded="false">⋯</button>
      </div>`;
  };

  const pinnedMarkup = pinnedSessions.length
    ? `<section class="sidebar-list-section pinned-section">
        <div class="sidebar-list-section-label">置顶</div>
        <div class="pinned-session-list">${pinnedSessions.map(session => renderSessionRow(session, { pinnedSection: true })).join('')}</div>
      </section>`
    : '';

  const allProjectsCollapsed = visibleGroups.length > 0 && visibleGroups.every(group => collapsedWorkspaceGroups.has(group.key));
  const projectToggleIcon = allProjectsCollapsed
    ? '<svg class="project-toggle-icon is-expand" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 3H20.5C20.77614 3 21 3.22386 21 3.5V10M14 10L20.4 3.6M10 21H3.5C3.22386 21 3 20.77614 3 20.5V14M10 14L3.6 20.4"/></svg>'
    : '<svg class="project-toggle-icon is-collapse" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M21 10H14.5C14.22386 10 14 9.77614 14 9.5V3M14.6 9.4L21 3M3 14H9.5C9.77614 14 10 14.22386 10 14.5V21M9.4 14.6L3 21"/></svg>';
  const projectsMarkup = visibleGroups.length
    ? `<section class="sidebar-list-section projects-section">
        <div class="sidebar-list-section-header project-section-header">
          <span class="sidebar-list-section-label">项目</span>
          <div class="project-section-actions" aria-label="项目视图操作">
            <button type="button" class="project-section-action" data-project-view-action="toggle" title="${allProjectsCollapsed ? '展开所有工作区' : '折叠所有工作区'}" aria-label="${allProjectsCollapsed ? '展开所有工作区' : '折叠所有工作区'}">
              ${projectToggleIcon}
            </button>
          </div>
        </div>
        <div class="workspace-groups">${visibleGroups.map(group => {
    const collapsed = collapsedWorkspaceGroups.has(group.key);
    const meta = workspaceSidebarMeta[group.key] || {};
    const groupDead = group.sessions.some(session => session.workspaceMissing === true);
    const tasks = [...group.sessions]
      .sort((a, b) => {
        if (!!a.pinned !== !!b.pinned) return a.pinned ? -1 : 1;
        return (Number(b.updatedAt) || 0) - (Number(a.updatedAt) || 0);
      })
      .map(s => renderSessionRow(s)).join('');

    return `
      <section class="workspace-group ${collapsed ? 'is-collapsed' : ''} ${groupDead ? 'is-dead-workspace' : ''}" data-workspace-group="${escapeAttr(group.key)}">
        <div class="workspace-header" data-workspace-toggle="${escapeAttr(group.key)}" title="${escapeAttr(group.workspace || '未选择工作区')}" tabindex="0"${groupDead ? ' data-dead-workspace="true"' : ''}>
          <span class="workspace-icon" data-workspace-folder-state="${collapsed ? 'closed' : 'open'}">${collapsed ? ICONS.folder : ICONS.folderOpen}</span>
          <span class="workspace-name">${escapeHtml(group.label)}</span>
          ${meta.pinned ? `<button type="button" class="workspace-pin" data-workspace-pin-toggle="${escapeAttr(group.key)}" title="取消置顶工作区" aria-label="取消置顶工作区">${ICONS.pin}</button>` : ''}
          <button type="button" class="workspace-more-btn" data-workspace-menu-toggle="${escapeAttr(group.key)}" aria-label="工作区操作" aria-expanded="false">⋯</button>
        </div>
        <div class="workspace-task-list">${tasks}</div>
      </section>`;
        }).join('')}</div>
      </section>`
    : '';

  list.innerHTML = pinnedMarkup + projectsMarkup;
  trackSessionTitleOverflow(list);

  list.querySelectorAll('[data-project-view-action]').forEach(button => {
    button.addEventListener('click', event => {
      event.stopPropagation();
      const action = button.dataset.projectViewAction;
      const shouldExpand = visibleGroups.some(group => !collapsedWorkspaceGroups.has(group.key));
      visibleGroups.forEach(group => {
        if (action === 'toggle' && shouldExpand) collapsedWorkspaceGroups.add(group.key);
        else if (action === 'toggle') collapsedWorkspaceGroups.delete(group.key);
      });
      saveCollapsedWorkspaceGroups();
      renderSessionList();
    });
  });

  list.querySelectorAll('[data-workspace-pin-toggle]').forEach(button => {
    button.addEventListener('click', event => {
      event.stopPropagation();
      const key = button.dataset.workspacePinToggle || '';
      if (!workspaceSidebarMeta[key]) return;
      workspaceSidebarMeta[key] = { ...workspaceSidebarMeta[key], pinned: false };
      saveWorkspaceSidebarMeta();
      renderSessionList();
    });
  });

  list.querySelectorAll('[data-workspace-toggle]').forEach(header => {
    const toggle = () => {
      const key = header.dataset.workspaceToggle;
      if (collapsedWorkspaceGroups.has(key)) collapsedWorkspaceGroups.delete(key);
      else collapsedWorkspaceGroups.add(key);
      saveCollapsedWorkspaceGroups();
      renderSessionList();
    };
    header.addEventListener('click', event => {
      if (event.target.closest('[data-workspace-menu-toggle]')) return;
      toggle();
    });
    header.addEventListener('keydown', event => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        toggle();
      }
    });
  });

  list.querySelectorAll('[data-workspace-menu-toggle]').forEach(button => {
    button.addEventListener('click', event => {
      event.stopPropagation();
      const key = button.dataset.workspaceMenuToggle || '';
      const group = visibleGroups.find(item => item.key === key);
      if (!group) return;
      const meta = workspaceSidebarMeta[key] || {};
      const items = [{
        label: meta.pinned ? '取消置顶工作区' : '置顶工作区',
        icon: ICONS.pin,
        onSelect: () => {
          workspaceSidebarMeta[key] = { ...meta, pinned: !meta.pinned, hidden: false };
          saveWorkspaceSidebarMeta();
          renderSessionList();
        }
      }];
      if (group.workspace) {
        items.push({
          label: '在资源管理器中打开',
          icon: ICONS.folder,
          onSelect: async () => {
            const result = await api.openWorkspaceInExplorer?.(group.workspace);
            if (result?.ok === false) toast(result.error || '打开工作区失败');
          }
        }, {
          label: '移除工作区',
          icon: ICONS.trash,
          danger: true,
          onSelect: async () => {
            const confirmed = await requestWorkspaceRemovalConfirmation(group);
            if (!confirmed) return;
            workspaceSidebarMeta[key] = { ...(workspaceSidebarMeta[key] || {}), hidden: true };
            saveWorkspaceSidebarMeta();
            renderSessionList();
            toast('工作区已从任务列表移除，文件与任务未删除');
          }
        });
      }
      openSidebarContextMenu(button, items);
    });
  });

  list.querySelectorAll('[data-session-menu-toggle]').forEach(button => {
    button.addEventListener('click', event => {
      event.stopPropagation();
      const id = button.dataset.sessionMenuToggle || '';
      const session = state.sessions.find(item => item.id === id);
      if (!session) return;
      openSidebarContextMenu(button, [{
        label: session.pinned ? '取消置顶任务' : '置顶任务',
        icon: ICONS.pin,
        onSelect: () => toggleSessionPinnedFromSidebar(session)
      }, {
        label: '移除任务',
        icon: ICONS.trash,
        danger: true,
        onSelect: () => deleteSessionFromSidebar(id)
      }]);
    });
  });

  list.querySelectorAll('.session-item').forEach(el => {
    el.addEventListener('click', async (e) => {
      if (e.target.closest('[data-session-menu-toggle]')) return;
      switchSidebarNav('tasks');
      const summary = state.sessions.find(session => session.id === el.dataset.id);
      if (summary?.workspaceMissing) {
        await confirmDeadWorkspaceCleanup(summary);
        return;
      }
      loadSession(el.dataset.id);
    });
  });
}

// A workspace folder that no longer exists invalidates every task bound to
// it: opening any of them asks once, then deletes the whole group and lands
// the user on a Blank session.
async function confirmDeadWorkspaceCleanup(summary) {
  const confirmed = await requestGenericConfirmation({
    title: '工作区已被删除',
    description: '该任务所在的工作区已被删除 Yan Agent不再允许打开它并会立即删除',
    confirmLabel: '确定',
    danger: true
  });
  if (!confirmed) return;
  const workspace = String(summary.workspace || '');
  const doomed = state.sessions.filter(session => (
    session.workspaceMissing === true && String(session.workspace || '') === workspace
  ));
  const currentAmongDoomed = doomed.some(session => session.id === state.currentSession?.id);
  for (const session of doomed) {
    try {
      const result = await api.deleteSession(session.id, true);
      if (result?.ok !== false) {
        await clearYanCoreQueuedIntentsForThread(session.id, 'dead_workspace_session_removed');
        state.composerDrafts.delete(String(session.id));
        state.queuedTurns.delete(String(session.id));
      }
    } catch (error) {
      console.warn('[dead-workspace] session delete failed:', error);
    }
  }
  await refreshSessions();
  if (currentAmongDoomed || state.currentSession?.workspaceMissing) {
    state.config = await api.setConfig({ workspace: '' });
    await newSession();
  } else {
    renderSessionList();
  }
}

let newSessionPromise = null;

async function newSession() {
  if (newSessionPromise) return newSessionPromise;
  newSessionPromise = createOrActivateNewSession();
  try {
    return await newSessionPromise;
  } finally {
    newSessionPromise = null;
  }
}

async function createOrActivateNewSession() {
  cancelPromptOptimization({ announce: false });
  closeModelPicker();
  closeReasoningPicker();
  switchSidebarNav('tasks');
  // A new task inherits the current task's home: a blank task stays blank, a
  // task inside workspace A opens the next task inside A.
  const inheritedWorkspace = String(state.currentSession?.workspace || '').trim();
  const existing = inheritedWorkspace
    ? state.sessions.find(session => (
        isBlankNewChat(session)
        && String(session.workspace || '').trim() === inheritedWorkspace
      ))
    : state.sessions.find(isBlankUnassignedNewChat);
  if (existing) {
    if (state.currentSession?.id !== existing.id) {
      if (state.currentSession?.id) pauseUiForSession(state.currentSession.id);
      await loadSession(existing.id);
    }
    return existing;
  }
  if (state.currentSession?.id) {
    captureComposerDraftForSession(state.currentSession.id);
    pauseUiForSession(state.currentSession.id);
  }
  showSessionLoading('正在创建新对话…');
  const s = await api.createSession(Boolean(inheritedWorkspace), inheritedWorkspace);
  if (!s) {
    showSessionLoading('无法创建新对话');
    return null;
  }
  state.currentSession = s;
  syncAgentBrowserVisibility();
  syncPetFocusedSession(s);
  restoreComposerDraftForSession(s.id);
  clearMessages();
  setEmptyState(true);
  state.config = inheritedWorkspace
    ? await api.activateWorkspace(inheritedWorkspace)
    : await api.setConfig({ workspace: '' });
  await renderRightSidebarReview({ force: true });
  syncCurrentSessionAgentUi(s);
  updateTaskBar();
  updateSendState();
  await refreshSessions();
}

async function loadSession(id) {
  cancelPromptOptimization({ announce: false });
  const summary = state.sessions.find(session => session.id === String(id));
  if (summary?.workspaceMissing) {
    await confirmDeadWorkspaceCleanup(summary);
    return;
  }
  const previousSessionId = String(state.currentSession?.id || '');
  const switchingSessions = Boolean(previousSessionId && previousSessionId !== String(id));
  if (switchingSessions) {
    closeModelPicker();
    closeReasoningPicker();
    captureComposerDraftForSession(previousSessionId);
    pauseUiForSession(previousSessionId);
    showSessionLoading();
  }
  const activeEntry = state.activeRuns.get(id);
  const s = activeEntry?.sessionRef || await api.getSession(id, { messageLimit: MESSAGE_LOAD_LIMIT });
  if (!s) {
    showSessionLoading('任务打开失败');
    return;
  }
  markSessionLoadBaseline(s);
  state.currentSession = s;
  syncAgentBrowserVisibility();
  syncPetFocusedSession(s);
  if (!previousSessionId || switchingSessions) restoreComposerDraftForSession(s.id);
  // Render the target conversation as soon as the session data arrives; the
  // remaining workspace/review setup below must not delay the visible switch.
  renderMessages(s.messages || []);
  setEmptyState((s.messages || []).length === 0);
  ensureEarlierMessagesBar(s);
  state.config = await api.setConfig({ workspace: s.workspace || '' });

  const runCtx = getRunCtx(s.id);
  syncCurrentSessionAgentUi(s);
  if (runCtx) bindActiveRunUi(s.id);
  else showTyping(false);
  await renderRightSidebarReview({ force: true });
  updateTaskBar();
  updateSendState();
  renderSessionList();
}

async function saveCurrentSession(session = state.currentSession) {
  if (!session) return;
  if ((!session.title || session.title === 'New chat' || session.title === '新对话') &&
      session.messages && session.messages.length) {
    const firstUser = session.messages.find(m => m.role === 'user');
    if (firstUser) {
      const title = deriveTitle(firstUser.content);
      session.title = title;
      await api.renameSession(session.id, title);
      if (state.currentSession?.id === session.id) syncPetFocusedSession(session);
    }
  }
  await api.saveSession(buildSessionSavePayload(session));
  await refreshSessions();
  if (state.currentSession?.id === session.id) updateTaskBar();
}

function deriveTitle(text) {
  const clean = String(text).replace(/\s+/g, ' ').trim();
  return clean.length > 30 ? clean.slice(0, 30) + '…' : clean;
}

function displaySessionTitle(title) {
  return isDefaultSessionTitle(title) ? '新对话' : title;
}

// ============================================================
// Sidebar toggle
// ============================================================
$('#sidebarToggle').addEventListener('click', () => {
  if (currentWindowView !== 'main') return;
  setLeftSidebarOpen($('#app').classList.contains('sidebar-hidden'));
});

// ============================================================
// Messages rendering
// ============================================================
// Rendering a long conversation in one synchronous pass blocked the renderer
// main thread for hundreds of milliseconds (window fully frozen while the
// frames stopped). The tail of the conversation is what the user sees after a
// switch, so render that immediately and prepend the remaining older messages
// in animation-frame chunks with scroll anchoring.
const MESSAGE_RENDER_IMMEDIATE = 24;
const MESSAGE_RENDER_CHUNK = 10;
let historyPrependToken = 0;
let stopSessionEntryFollow = null;

function followSessionEntryBottom() {
  stopSessionEntryFollow?.();
  const sc = $('#chatScroll');
  const wrap = $('#messages');
  if (!sc || !wrap) return;
  const sessionId = currentChatSessionId();
  let frame = 0;
  const schedule = () => {
    if (frame) return;
    frame = requestAnimationFrame(() => {
      frame = 0;
      if (sessionId !== currentChatSessionId()) { stop(); return; }
      scrollChatToBottom({ instant: true, force: true });
    });
  };
  const observer = new ResizeObserver(schedule);
  const stop = () => {
    observer.disconnect();
    if (frame) cancelAnimationFrame(frame);
    sc.removeEventListener('wheel', stop);
    sc.removeEventListener('touchstart', stop);
    sc.removeEventListener('pointerdown', stop);
    document.removeEventListener('keydown', onKey);
    if (stopSessionEntryFollow === stop) stopSessionEntryFollow = null;
  };
  const onKey = event => {
    if (['ArrowUp', 'ArrowDown', 'PageUp', 'PageDown', 'Home', 'End', ' '].includes(event.key)) stop();
  };
  stopSessionEntryFollow = stop;
  observer.observe(wrap);
  observer.observe(sc);
  sc.addEventListener('wheel', stop, { passive: true });
  sc.addEventListener('touchstart', stop, { passive: true });
  sc.addEventListener('pointerdown', stop, { passive: true });
  document.addEventListener('keydown', onKey);
  schedule();
}

function clearMessages() {
  stopSessionEntryFollow?.();
  historyPrependToken++;
  $('#messages').innerHTML = '';
  invalidateConversationTurns();
  renderTurnScaleNavigation();
}

// Session switching is asynchronous: replace the previous conversation with a
// loading placeholder immediately, so a slow getSession/createSession can never
// leave the previous task on screen while the switch is pending.
function showSessionLoading(label = '正在打开任务…') {
  stopSessionEntryFollow?.();
  historyPrependToken++;
  const wrap = $('#messages');
  if (!wrap) return;
  wrap.innerHTML = `<div class="session-loading" role="status" aria-live="polite"><span class="session-loading-spinner" aria-hidden="true"></span><span class="session-loading-label">${escapeHtml(label)}</span></div>`;
  invalidateConversationTurns();
  renderTurnScaleNavigation();
}

// Rendering a long conversation in one synchronous pass blocked the renderer
// main thread for hundreds of milliseconds — the comment above on
function buildHistoryMessageElement(message, index) {
  const element = appendMessage(
    message.role,
    message.content,
    message.attachments,
    false,
    index,
    message.ts,
    message.duration,
    message.agentRun,
    message.skillCalls || message.skillCall,
    message.mediaAssets?.length ? message.mediaAssets : message.media
  );
  if (message.role === 'user' && message.modelSwitchNotice) {
    appendModelSwitchNoticeElement(message.modelSwitchNotice, { animate: false });
  }
  return element;
}

function scheduleHistoryPrepend(list, boundaryIndex) {
  const token = historyPrependToken;
  let chunkEnd = boundaryIndex;
  const step = () => {
    if (token !== historyPrependToken) return;
    const chunkStart = Math.max(0, chunkEnd - MESSAGE_RENDER_CHUNK);
    if (chunkStart >= chunkEnd) return;
    const wrap = $('#messages');
    const sc = $('#chatScroll');
    const anchor = sc ? { height: sc.scrollHeight, top: sc.scrollTop } : null;
    suppressChatAutoScroll = true;
    try {
      // Anchor at the oldest rendered message, not the container's first
      // child: the earlier-messages bar (when present) must stay on top.
      const first = wrap.querySelector('.msg');
      const builtBefore = wrap.children.length;
      for (let i = chunkStart; i < chunkEnd; i++) buildHistoryMessageElement(list[i], i);
      if (first) {
        const fragment = document.createDocumentFragment();
        while (wrap.children.length > builtBefore) fragment.appendChild(wrap.children[builtBefore]);
        wrap.insertBefore(fragment, first);
      }
    } finally {
      suppressChatAutoScroll = false;
    }
    // Content was inserted above the viewport; shift scrollTop by the height
    // delta so whatever the user was looking at stays pixel-stable.
    if (sc && anchor) sc.scrollTop = anchor.top + (sc.scrollHeight - anchor.height);
    invalidateConversationTurns();
    renderTurnScaleNavigation();
    chunkEnd = chunkStart;
    if (chunkStart > 0) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

function renderMessages(messages) {
  const sessionId = currentChatSessionId();
  if (sessionId && !state.activeRuns.has(sessionId)) chatAutoFollowBySession.delete(sessionId);
  syncChatAutoFollowUi(sessionId);
  historyPrependToken++;
  const list = Array.isArray(messages) ? messages : [];
  const immediateStart = Math.max(0, list.length - MESSAGE_RENDER_IMMEDIATE);
  suppressChatAutoScroll = true;
  try {
    clearMessages();
    for (let i = immediateStart; i < list.length; i++) buildHistoryMessageElement(list[i], i);
    renderTurnScaleNavigation();
  } finally {
    suppressChatAutoScroll = false;
  }
  // 历史记录一次性渲染完成后再定位到底部，避免逐条消息触发平滑滚动。
  followSessionEntryBottom();
  if (immediateStart > 0) scheduleHistoryPrepend(list, immediateStart);
  // clearMessages() wipes the earlier-messages bar; restore it when the
  // current session is still waiting for its older pages.
  ensureEarlierMessagesBar(state.currentSession);
}

// ============================================================
// On-demand history loading for oversized sessions
// ============================================================
// A task that ran for a long time accumulates tens of megabytes of messages
// (subagent work timelines, tool output). Shipping the whole session across
// IPC on every switch stalled the main process and the renderer for seconds.
// session:get now returns only the newest MESSAGE_LOAD_LIMIT messages; older
// pages load from the main-process cache when the user scrolls back up.
const MESSAGE_LOAD_LIMIT = 40;
const EARLIER_MESSAGES_PAGE = 60;
let earlierMessagesLoading = false;

// 采用(尾加载)会话时记录一次基线:内存里最初装了多少条消息、从磁盘哪个下标开始。
// 之后翻页只会扩大“磁盘派生前缀”;运行期间 push 的新消息不在磁盘头部里。
// 保存载荷据此裁剪,避免把翻页积累的完整历史整包克隆过 IPC。
function markSessionLoadBaseline(session) {
  if (!session || !Array.isArray(session.messages) || !session.messages.length) return;
  if (session.loadTailLength !== undefined) return; // 复用的运行中会话,保留旧基线
  const start = Number(session.messagesStart);
  if (!Number.isInteger(start) || start < 0) return;
  session.loadTailLength = session.messages.length;
  session.loadMessagesStart = start;
}

function buildSessionSavePayload(session) {
  const messages = Array.isArray(session.messages) ? session.messages : [];
  if (messages.length <= MESSAGE_LOAD_LIMIT) return session;
  const baselineStart = Number(session.loadMessagesStart);
  const baselineTail = Number(session.loadTailLength);
  const currentStart = Number(session.messagesStart);
  // 基线或当前偏移缺失时回退整包保存,与旧行为一致(宁可多传不可丢历史)
  if (!Number.isFinite(baselineStart) || !Number.isFinite(baselineTail)
    || !Number.isInteger(currentStart) || currentStart < 0) return session;
  // 磁盘派生前缀长度 = 载入时的尾部 + 之后翻页补齐的部分;
  // 裁剪点不能越过它,否则磁盘头部对不齐会丢消息
  const diskDerived = baselineTail + (baselineStart - currentStart);
  const tailStart = Math.min(messages.length - MESSAGE_LOAD_LIMIT, Math.max(0, diskDerived));
  if (!(tailStart > 0)) return session;
  const payload = {
    ...session,
    messages: messages.slice(tailStart),
    messagesStart: currentStart + tailStart,
    messagesTruncated: true,
    totalMessages: messages.length
  };
  delete payload.loadTailLength;
  delete payload.loadMessagesStart;
  return payload;
}

function rebaseRenderedMessageIndices(delta) {
  if (!delta) return;
  $$('#messages .msg[data-msg-index]').forEach(element => {
    const value = Number(element.dataset.msgIndex);
    if (Number.isInteger(value)) element.dataset.msgIndex = value + delta;
  });
}

function ensureEarlierMessagesBar(session) {
  const wrap = $('#messages');
  if (!wrap) return;
  const bar = wrap.querySelector('.earlier-messages-bar');
  if (!session?.messagesTruncated) {
    bar?.remove();
    return;
  }
  const remaining = Math.max(0, Number(session.messagesStart) || 0);
  const button = bar?.querySelector('button') || null;
  if (!bar || !button) {
    const next = document.createElement('div');
    next.className = 'earlier-messages-bar';
    next.innerHTML = '<button type="button" class="earlier-messages-btn">加载更早的消息</button>';
    next.querySelector('button').addEventListener('click', () => {
      void loadEarlierMessages();
    });
    wrap.insertBefore(next, wrap.firstElementChild);
    next.querySelector('button').textContent = `加载更早的消息（还有 ${remaining} 条）`;
    return;
  }
  button.textContent = `加载更早的消息（还有 ${remaining} 条）`;
}

async function loadEarlierMessages() {
  const session = state.currentSession;
  if (!session || earlierMessagesLoading) return;
  if (!session.messagesTruncated) {
    // Defense in depth: a bar left mounted after a silent full load must not be
    // permanently inert — reconcile the DOM and drop the stale bar.
    if (document.querySelector('#messages .earlier-messages-bar')) renderMessages(session.messages || []);
    return;
  }
  earlierMessagesLoading = true;
  const button = $('#messages .earlier-messages-bar button');
  if (button) button.textContent = '正在加载更早的消息…';
  try {
    await loadSessionHistoryBackwards(session, { render: true });
  } catch (error) {
    if (button) button.textContent = error?.message || '加载失败，点击重试';
  } finally {
    earlierMessagesLoading = false;
  }
}

// Pages come back capped by count AND accumulated size, so pull contiguous
// ranges that always end at messagesStart until the conversation is whole.
// A shorter page simply means the loop keeps pulling; ranges never overlap.
async function loadSessionHistoryBackwards(session, { render = false } = {}) {
  let guard = 0;
  while ((Number(session.messagesStart) || 0) > 0 && guard++ < 500) {
    const cursor = Number(session.messagesStart) || 0;
    const requestStart = Math.max(0, cursor - EARLIER_MESSAGES_PAGE);
    const result = await api.getSessionMessages(session.id, requestStart, cursor - requestStart);
    // The user may have switched sessions while the page was in flight;
    // never prepend another conversation's history into the DOM.
    if (render && state.currentSession !== session) return session;
    if (result?.ok === false || !Array.isArray(result?.messages) || !result.messages.length) {
      if (render) throw new Error(result?.error || '加载失败');
      break;
    }
    const page = result.messages;
    session.messages = [...page, ...(Array.isArray(session.messages) ? session.messages : [])];
    session.messagesStart = requestStart;
    if (requestStart <= 0) delete session.messagesTruncated;
    if (render) {
      rebaseRenderedMessageIndices(page.length);
      prependRenderedHistory(page, requestStart);
      ensureEarlierMessagesBar(session);
    }
  }
  session.totalMessages = Array.isArray(session.messages) ? session.messages.length : 0;
  if (render) ensureEarlierMessagesBar(session);
  return session;
}

// Run submission must always see the complete conversation (the kernel
// receives it as history), so pull every remaining page before starting work.
async function ensureFullSessionLoaded(session) {
  if (!session?.messagesTruncated) return session || null;
  await loadSessionHistoryBackwards(session, { render: false });
  // The silent load exists so the kernel receives the complete history. If
  // this session is on screen, the visible conversation (and its truncation
  // bar) must be reconciled too: deleting messagesTruncated without updating
  // the DOM left the bar mounted but its click silently early-returning.
  if (state.currentSession === session) renderMessages(session.messages || []);
  return session;
}

// Build message elements for a page and move them above the oldest rendered
// message, keeping the viewport anchored on the content being read.
function prependRenderedHistory(page, startIndex) {
  const wrap = $('#messages');
  if (!wrap || !page.length) return;
  const sc = $('#chatScroll');
  const anchor = sc ? { height: sc.scrollHeight, top: sc.scrollTop } : null;
  suppressChatAutoScroll = true;
  try {
    const oldest = wrap.querySelector('.msg');
    const builtBefore = wrap.children.length;
    for (let i = 0; i < page.length; i++) buildHistoryMessageElement(page[i], startIndex + i);
    if (oldest) {
      const fragment = document.createDocumentFragment();
      while (wrap.children.length > builtBefore) fragment.appendChild(wrap.children[builtBefore]);
      wrap.insertBefore(fragment, oldest);
    }
  } finally {
    suppressChatAutoScroll = false;
  }
  if (sc && anchor) sc.scrollTop = anchor.top + (sc.scrollHeight - anchor.height);
  invalidateConversationTurns();
  renderTurnScaleNavigation();
  scheduleTurnScaleUpdate();
}

function appendModelSwitchNoticeElement(text, { animate = true } = {}) {
  const value = String(text || '').trim();
  const wrap = $('#messages');
  if (!value || !wrap) return null;
  const element = document.createElement('div');
  element.className = 'model-switch-notice';
  element.textContent = value;
  if (!animate) element.style.animation = 'none';
  wrap.appendChild(element);
  return element;
}

function setEmptyState(empty) {
  $('#pageChat').classList.toggle('empty', empty);
  updateGuideHint(empty);
  scheduleTurnScaleUpdate();
}

let turnScaleFrame = 0;
let turnScaleActiveIndex = -1;
let conversationTurnsCache = null;
const TURN_SCALE_OFFSET_TTL_MS = 250;
let turnScaleOffsetCache = { turns: null, nodes: [], offsets: [], at: 0 };

function invalidateConversationTurns() {
  conversationTurnsCache = null;
  turnScaleOffsetCache.at = 0;
}

function getConversationTurns() {
  const messagesRoot = $('#messages');
  const messages = Array.from(messagesRoot?.children || [])
    .filter(element => element.classList?.contains('msg'));
  const cached = conversationTurnsCache;
  if (cached
    && cached.root === messagesRoot
    && cached.nodes.length === messages.length
    && cached.nodes.every((node, index) => node === messages[index])) {
    return cached.turns;
  }

  const turns = [];
  let currentTurn = null;
  for (const element of messages) {
    if (element.classList.contains('user')) {
      currentTurn = {
        index: turns.length,
        userEl: element,
        assistantEl: null,
        userText: element.querySelector('.msg-body')?.textContent?.replace(/\s+/g, ' ').trim() || '（没有文字内容）',
        assistantText: '（Agent 尚未回复）'
      };
      turns.push(currentTurn);
    } else if (element.classList.contains('assistant') && currentTurn && !currentTurn.assistantEl) {
      currentTurn.assistantEl = element;
      currentTurn.assistantText = element.querySelector('.msg-body')?.textContent?.replace(/\s+/g, ' ').trim() || '（Agent 尚未回复）';
    }
  }
  conversationTurnsCache = { root: messagesRoot, nodes: messages, turns };
  return turns;
}

function truncateTurnPreview(text, max = 96) {
  const value = String(text || '').replace(/\s+/g, ' ').trim();
  if (value.length <= max) return value;
  return `${value.slice(0, Math.max(1, max - 1))}…`;
}

let turnScaleFocusedElements = [];

function clearTurnScaleFocus() {
  for (const element of turnScaleFocusedElements) element?.classList.remove('turn-focus');
  turnScaleFocusedElements = [];
  const preview = $('#turnScalePreview');
  preview?.classList.add('hidden');
  $('#turnScaleNav')?.removeAttribute('data-hover-index');
}

function showTurnScalePreview(turn) {
  const nav = $('#turnScaleNav');
  const preview = $('#turnScalePreview');
  if (!nav || !preview || !turn) return;
  const userText = turn.userEl?.querySelector('.msg-body')?.textContent?.replace(/\s+/g, ' ').trim() || turn.userText;
  const assistantText = turn.assistantEl?.querySelector('.msg-body')?.textContent?.replace(/\s+/g, ' ').trim() || '（Agent 尚未回复）';
  clearTurnScaleFocus();
  turn.userEl?.classList.add('turn-focus');
  turn.assistantEl?.classList.add('turn-focus');
  turnScaleFocusedElements = [turn.userEl, turn.assistantEl].filter(Boolean);
  nav.dataset.hoverIndex = String(turn.index);
  preview.innerHTML = `
    <p class="turn-scale-preview-user">${escapeHtml(truncateTurnPreview(userText))}</p>
    <p class="turn-scale-preview-agent">${escapeHtml(truncateTurnPreview(assistantText))}</p>`;
  preview.classList.remove('hidden');
  const tick = $(`.turn-scale-tick[data-turn-index="${turn.index}"]`, nav);
  const viewport = $('.turn-scale-viewport', nav);
  if (tick && viewport) {
    const top = tick.offsetTop - viewport.scrollTop + tick.offsetHeight / 2;
    preview.style.top = `${Math.max(12, Math.min(nav.clientHeight - preview.offsetHeight - 12, top - preview.offsetHeight / 2))}px`;
  }
}

function renderTurnScaleNavigation() {
  const nav = $('#turnScaleNav');
  const scroller = $('#chatScroll');
  if (!nav || !scroller) return;
  const turns = getConversationTurns();
  const shouldShow = turns.length > 0;
  nav.classList.toggle('hidden', !shouldShow);
  if (!shouldShow) {
    nav.innerHTML = '';
    nav.classList.remove('is-overflowing');
    nav.removeAttribute('data-hover-index');
    turnScaleActiveIndex = -1;
    return;
  }
  turnScaleActiveIndex = -1;
  turnScaleOffsetCache.at = 0;

  nav.innerHTML = `
    <div class="turn-scale-viewport" tabindex="0" aria-label="对话回合刻度，可滚动浏览">
      <div class="turn-scale-track">${turns.map(turn => {
        const label = `第 ${turn.index + 1} 回合：${truncateTurnPreview(turn.userText, 48)}`;
        return `<button type="button" class="turn-scale-tick" data-turn-index="${turn.index}" title="${escapeAttr(label)}" aria-label="${escapeAttr(label)}"></button>`;
      }).join('')}</div>
    </div>
    <div id="turnScalePreview" class="turn-scale-preview hidden" role="tooltip"></div>`;

  const viewport = $('.turn-scale-viewport', nav);
  const track = $('.turn-scale-track', nav);
  viewport?.addEventListener('scroll', () => {
    updateTurnScaleNavigation();
    const index = Number(nav.dataset.hoverIndex);
    if (Number.isInteger(index) && turns[index]) showTurnScalePreview(turns[index]);
  }, { passive: true });
  if (nav.dataset.focusBound !== 'true') {
    nav.addEventListener('mouseleave', clearTurnScaleFocus);
    nav.dataset.focusBound = 'true';
  }
  nav.querySelectorAll('.turn-scale-tick').forEach(button => {
    const turn = turns[Number(button.dataset.turnIndex)];
    button.addEventListener('mouseenter', () => showTurnScalePreview(turn));
    button.addEventListener('focus', () => showTurnScalePreview(turn));
    button.addEventListener('click', () => {
      if (!turn?.userEl) return;
      scroller.scrollTo({
        top: Math.max(0, turn.userEl.offsetTop - scroller.clientHeight * 0.35),
        behavior: 'smooth'
      });
    });
  });
  requestAnimationFrame(() => {
    if (!viewport || !track) return;
    nav.classList.toggle('is-overflowing', track.scrollHeight > viewport.clientHeight + 2);
    viewport.scrollTop = Math.max(0, track.scrollHeight - viewport.clientHeight);
    updateTurnScaleNavigation();
  });
}

function turnScaleOffsets(turns) {
  const now = performance.now();
  const cached = turnScaleOffsetCache;
  const fresh = cached.turns === turns
    && cached.offsets.length === turns.length
    && cached.nodes.length === turns.length
    && cached.nodes.every((node, index) => node === turns[index].userEl)
    && now - cached.at < TURN_SCALE_OFFSET_TTL_MS;
  if (fresh) return cached.offsets;
  const nodes = turns.map(turn => turn.userEl);
  const offsets = nodes.map(element => (element?.isConnected ? element.offsetTop : null));
  turnScaleOffsetCache = { turns, nodes, offsets, at: now };
  return offsets;
}

function updateTurnScaleNavigation() {
  const nav = $('#turnScaleNav');
  const scroller = $('#chatScroll');
  if (!nav || nav.classList.contains('hidden') || !scroller) return;
  const turns = getConversationTurns();
  const ticks = $$('.turn-scale-tick', nav);
  if (turns.length !== ticks.length) {
    renderTurnScaleNavigation();
    return;
  }

  const anchor = scroller.scrollTop + scroller.clientHeight * 0.42;
  const offsets = turnScaleOffsets(turns);
  let activeIndex = 0;
  turns.forEach((turn, index) => {
    const offset = offsets[index];
    if (Number.isFinite(offset) && offset <= anchor) activeIndex = index;
  });
  if (activeIndex === turnScaleActiveIndex) return;
  turnScaleActiveIndex = activeIndex;
  ticks.forEach((tick, index) => {
    const active = index === activeIndex;
    tick.classList.toggle('active', active);
    if (active) tick.setAttribute('aria-current', 'step');
    else tick.removeAttribute('aria-current');
  });
}

function scheduleTurnScaleUpdate() {
  if (turnScaleFrame) cancelAnimationFrame(turnScaleFrame);
  turnScaleFrame = requestAnimationFrame(() => {
    turnScaleFrame = 0;
    const nav = $('#turnScaleNav');
    const scroller = $('#chatScroll');
    const turns = getConversationTurns();
    const shouldShow = turns.length > 0;
    if (!!nav && nav.classList.contains('hidden') === shouldShow) renderTurnScaleNavigation();
    else updateTurnScaleNavigation();
  });
}

// ============================================================
