let currentMainPage = 'chat';
let currentWindowView = 'main';
let mainSidebarWasOpen = true;
let activeRightSidebarTab = null;
const openRightSidebarTabs = [];
const SUBAGENT_UI_NAMES = window.YanSubagentWorkflow?.NAMES || {};
const subagentPanel = window.YanSubagentPanel?.create?.({
  getSessionId: () => String(state.currentSession?.id || ''),
  getRuns: () => {
    const session = state.currentSession;
    if (!session) return [];
    const runs = new Map();
    for (const [index, message] of (session.messages || []).entries()) {
      if (!message.agentRun) continue;
      const run = message.agentRun;
      run.runId ||= session.id + ':history:' + (message.ts || index);
      runs.set(run.runId, run);
    }
    const live = getRunCtx(session.id)?.activeAgentRun;
    if (live) runs.set(live.runId, live);
    return [...runs.values()];
  },
  renderNative: (body, run, fallback) => renderAgentRunBody(body, run, fallback),
  renderActions: (body, run, copyText) => {
    let actions = body.querySelector(':scope > .msg-actions');
    if (!actions) {
      actions = document.createElement('div');
      actions.className = 'msg-actions';
      body.appendChild(actions);
    }
    actions.innerHTML = buildAssistantActionsHtml(run, run.durationMs, run.completedAt);
    actions.querySelector('.msg-action-btn')?.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText(copyText || '');
        toast('已复制到剪贴板');
      } catch { toast('复制失败'); }
    });
    bindAgentWorkToggle(body);
    syncAgentWorkVisibility(body.querySelector('.agent-run-header'));
  },
  openSidebar: () => openRightSidebarTool('subagents'),
  escapeHtml: value => escapeAttr(String(value || ''))
}) || { render() {}, schedule() {}, open() {}, openRoot() {} };
function renderSubagentUi() { subagentPanel.render(); }
function updateSubagentWorkflow(runCtx, event, deferEffects) {
  const run = runCtx.activeAgentRun;
  if (!run) return false;
  run.runId ||= runCtx.runId;
  const previousTimelineLength = run.timeline?.length || 0;
  const update = window.YanSubagentWorkflow?.consume?.(run, event);
  if (!update?.handled) return false;
  // Child-session activity (token deltas, tool churn) belongs to the subagent
  // panel; it must not invalidate the parent message projection. Only a real
  // parent-row notice may do that — otherwise a build subagent streaming for
  // minutes forced a full parent reconcile every 100ms and froze long tasks.
  if (update.timelineChanged) {
    // The workflow store may update an existing timeline object in place, so a
    // length check alone cannot invalidate the cached render projection.
    runCtx.openCodeTimelineRevision = (Number(runCtx.openCodeTimelineRevision) || 0) + 1;
    run.uiTimelineRevision = runCtx.openCodeTimelineRevision;
    if (previousTimelineLength !== run.timeline.length) rebuildOpenCodeTimelineIndex(runCtx);
    if (update.timelineKey) runCtx.openCodeDirtyTimelineKeys?.add(String(update.timelineKey));
    if (!deferEffects) scheduleOpenCodeRender(runCtx);
  }
  if (state.currentSession?.id === runCtx.sessionId) {
    if (update.created && !runCtx.replayingSubagents) subagentPanel.open();
    else subagentPanel.schedule();
  }
  return true;
}
let rightSidebarBrowserCounter = 0;
const RIGHT_SIDEBAR_TAB_MIN_WIDTH = 92;
const RIGHT_SIDEBAR_TAB_MAX_WIDTH = 220;
let rightSidebarTabLayoutFrame = 0;
let rightSidebarTabLayoutObserver = null;
let browserFocusMode = false;
let browserFocusStoredRightWidth = '';
let browserFocusComposerMode = 'standby';
const mediaStudioState = {
  mode: 'image',
  aspectRatio: '16:9',
  durationSeconds: 5,
  resolution: '720p',
  models: [],
  sourceImage: null,
  sourceObjectUrl: '',
  requestId: '',
  running: false,
  cancelRequested: false,
  resultAssetId: '',
  petRunCtx: null
};
// Tool selection belongs to the task, not to the shared task-bar component.
const taskToolSelections = new Map();
let vsCodeStatus = { available: false, executable: '', iconDataUrl: '' };
let skillMarketFilter = 'all';
let skillMarketCatalog = [];
let skillMarketAllCatalog = [];
