$('#rs-review')?.addEventListener('click', event => {
  const navigation = event.target.closest('#reviewPreviousFileBtn, #reviewNextFileBtn');
  if (navigation) {
    const files = Array.isArray(rsReviewState.summary?.files) ? rsReviewState.summary.files : [];
    const index = files.findIndex(file => file.path === rsReviewState.selectedPath);
    if (navigation.id === 'reviewPreviousFileBtn' && index > 0) selectReviewFile(index - 1);
    if (navigation.id === 'reviewNextFileBtn' && index >= 0 && index < files.length - 1) selectReviewFile(index + 1);
    return;
  }
  const scopePill = event.target.closest('[data-review-scope]');
  if (scopePill) {
    const scope = scopePill.dataset.reviewScope === 'staged' ? 'staged' : 'worktree';
    if (scope === rsReviewState.scope) return;
    rsReviewState.scope = scope;
    rsReviewState.summary = null;
    rsReviewState.documentCache.clear();
    rsReviewState.selectedPath = '';
    rsReviewState.openComposerKey = '';
    void renderRightSidebarReview({ force: true });
    return;
  }
  const noteTrigger = event.target.closest('[data-review-note-trigger]');
  if (noteTrigger) {
    rsReviewState.openComposerKey = rsReviewState.selectedPath + '::' + (noteTrigger.dataset.reviewNoteTrigger || '');
    renderReviewDiff();
    return;
  }
  const composerRoot = event.target.closest('[data-review-composer]');
  if (composerRoot) {
    const textarea = composerRoot.querySelector('textarea');
    if (event.target.closest('[data-review-composer-cancel]')) {
      rsReviewState.openComposerKey = '';
      renderReviewDiff();
    } else if (event.target.closest('[data-review-composer-save]')) {
      const text = String(textarea?.value || '').trim();
      if (!text || !textarea) return;
      const [filePath, key] = String(rsReviewState.openComposerKey || '').split('::');
      if (!filePath || !key) return;
      const label = key.startsWith('n')
        ? '第 ' + key.slice(1) + ' 行'
        : '原第 ' + key.slice(1) + ' 行';
      const notes = Array.isArray(rsReviewState.comments[filePath]) ? rsReviewState.comments[filePath] : [];
      notes.push({ key, label, text, at: Date.now() });
      notes.sort((a, b) => String(a.key).localeCompare(String(b.key), undefined, { numeric: true }));
      rsReviewState.comments[filePath] = notes;
      rsReviewState.openComposerKey = '';
      renderReviewDiff();
    }
    return;
  }
  const noteRemove = event.target.closest('[data-review-note-remove]');
  if (noteRemove) {
    const notes = Array.isArray(rsReviewState.comments[rsReviewState.selectedPath])
      ? rsReviewState.comments[rsReviewState.selectedPath]
      : [];
    rsReviewState.comments[rsReviewState.selectedPath] = notes.filter(note => note.key !== noteRemove.dataset.reviewNoteRemove);
    renderReviewDiff();
    return;
  }
  const actionButton = event.target.closest('[data-review-action]');
  if (actionButton) {
    const action = actionButton.dataset.reviewAction;
    if (action === 'send') {
      reviewSendCommentsToAgent(rsReviewState.selectedPath);
      return;
    }
    if (action === 'discard') {
      if (!actionButton.classList.contains('is-armed')) {
        actionButton.classList.add('is-armed');
        actionButton.textContent = '确认丢弃';
        setTimeout(() => {
          if (actionButton.isConnected) {
            actionButton.classList.remove('is-armed');
            actionButton.textContent = '丢弃';
          }
        }, 3600);
        return;
      }
      void reviewRunFileAction('discard', rsReviewState.selectedPath);
      return;
    }
    void reviewRunFileAction(action === 'unstage' ? 'unstage' : 'stage', rsReviewState.selectedPath);
  }
});
