document.addEventListener('click', event => {
  const agentLink = event.target.closest?.('a[data-yan-browser-link]');
  if (agentLink?.closest('.msg-body.agent-output')) {
    const targetUrl = agentLink.dataset.yanBrowserLink || agentLink.getAttribute('href') || '';
    // Workspace screenshots are local image files: they belong to the same
    // preview window as attachments and generated images, not the side panel.
    const imagePath = localImagePathFromUrl(targetUrl);
    if (imagePath) {
      event.preventDefault();
      event.stopPropagation();
      openAttachmentPreview({ path: imagePath, name: '' });
      return;
    }
    const localPath = filePathFromAgentUrl(targetUrl);
    if (localPath && api.previewLocalFile) {
      event.preventDefault();
      event.stopPropagation();
      void api.previewLocalFile(localPath).then(result => {
        if (!result?.ok) {
          toast(result?.error || '无法打开路径');
          return;
        }
        if (result.action === 'browser' && result.url && openBrowserUrlInNewTab(result.url)) return;
        if (result.warning) toast(result.warning);
      }).catch(error => toast(error.message || '无法打开路径'));
      return;
    }
    if (openBrowserUrlInNewTab(targetUrl)) {
      event.preventDefault();
      event.stopPropagation();
      return;
    }
  }
  if (!event.target.closest('#rightSidebarAddWrap')) setRightSidebarAddMenuOpen(false);
  if (!event.target.closest('#rightSidebarTabOverflowWrap')) setRightSidebarTabOverflowMenuOpen(false);
  if (!event.target.closest('[data-browser-settings-wrap]')) closeAllBrowserSettingsMenus();
});
